input.sparql:
SELECT ?zone ?ts WHERE {
  ?zone brick:hasLabel ?lbl .
  FILTER(?lbl IN ("Perimeter_top_ZN_2", "DataCenter_top_ZN_6"))
  ?zone ref:hasTimeseriesId ?ts .
}

SELECT ?zone ?class ?ts WHERE {
  ?zone brick:hasLabel ?lbl .
  FILTER(?lbl IN ("Perimeter_top_ZN_2", "DataCenter_top_ZN_6"))
  ?zone a ?class .
  ?zone ref:hasTimeseriesId ?ts .
}

SELECT ?p ?t WHERE {
  ?p a brick:Occupancy_Sensor .
  ?p ref:hasTimeseriesId ?t .
} LIMIT 5
